fsl:DB-files-stat () 
{ 
    local jq='$ARGS.positional as [ $node, $path ] | $path / "/" | map(select(length > 0)) | join("-") as $tag | "tmp/\($node)-\($tag).db"';
    : ${2:?};
    bajl:self -nr --args "$@"
}
fsl:DB-files-stat-period () 
{ 
    local jq='$ARGS.positional as [ $period, $node, $path ] | $path / "/" | map(select(length > 0)) | join("-") as $tag | "out/\($node)-\($tag)-\($period)"';
    : ${2:?};
    bajl:self -nr --args "$@"
}
fsl:db-activity () 
{ 
    local sql='WITH deltas AS (
  SELECT
    date,
    path[1] AS db,
    size - LAG(size) OVER (PARTITION BY path ORDER BY date) AS growth
  FROM fsdb
  WHERE len(path) = 2
)
SELECT
  date,
  db,
  sum(growth) AS growth
FROM deltas
WHERE growth > 0
GROUP BY date, db
ORDER BY date, growth DESC';
    fsl:run-sql "$@"
}
fsl:db-growth () 
{ 
    local sql='SELECT
  date,
  path[1] AS db,
  SUM(size) AS size
FROM fsdb
WHERE len(path) = 2
GROUP BY date, db
ORDER BY date, size DESC';
    local db=$(DB-files-stat "${@:1:2}");
    shift 2;
    jq -nr "\"$sql\"" "" | duckdb "$db" "$@"
}
fsl:db-growth-pivot () 
{ 
    local sql='PIVOT (
  WITH deltas AS (
    SELECT
      date,
      path[1] AS db,
      -- Handle NULL (Deleted) vs Value. 
      -- If Current is NULL, treat as 0. If Prev is NULL, treat as 0.
      COALESCE(size, 0) - COALESCE(LAG(size) OVER (PARTITION BY path ORDER BY date), 0) AS growth
    FROM fsdb
    WHERE len(path) = 2
  ),
  binned AS (
    SELECT
      time_bucket(INTERVAL '\''\($interval)'\'', date) AS bucket,
      db,
      sum(growth) AS growth
    FROM deltas
    WHERE growth > 0  -- Remove this line to see Deletions (Negative growth)
    GROUP BY 1, 2
  ),
  source AS (
    SELECT strftime(bucket, '\''%m-%d %H:%M'\'') AS time, db, growth FROM binned
    UNION ALL
    SELECT '\''Total'\'' AS time, db, sum(growth) FROM binned GROUP BY db
    UNION ALL
    SELECT strftime(bucket, '\''%m-%d %H:%M'\'') AS time, '\'' Total'\'' AS db, sum(growth) FROM binned GROUP BY 1
    UNION ALL
    SELECT '\''Total'\'' AS time, '\'' Total'\'' AS db, sum(growth) FROM binned
  )
  SELECT * FROM source
)
ON time
USING round(sum(growth) / 1024 / 1024, 2)
ORDER BY Total DESC';
    local interval=${1:?};
    shift;
    local db=$(DB-files-stat "${@:1:2}");
    shift 2;
    jq -nr "\"$sql\"" "" --arg interval "$interval" | duckdb "$db" "$@"
}
fsl:db-growth-pivot-1 () 
{ 
    local sql='PIVOT (
  WITH deltas AS (
    SELECT
      date,
      path[1] AS db,
      size - LAG(size) OVER (PARTITION BY path ORDER BY date) AS growth
    FROM fsdb
    WHERE len(path) = 2
  ),
  binned AS (
    SELECT
      time_bucket(INTERVAL '\''\($interval)'\'', date) AS bucket,
      db,
      sum(growth) AS growth
    FROM deltas
    WHERE growth > 0
    GROUP BY 1, 2
  ),
  source AS (
    -- 1. Normal Data (DB per Time)
    SELECT strftime(bucket, '\''%m-%d %H:%M'\'') AS time, db, growth FROM binned
    UNION ALL
    -- 2. Total Column (Sum of Time per DB)
    SELECT '\''Total'\'' AS time, db, sum(growth) FROM binned GROUP BY db
    UNION ALL
    -- 3. Total Row (Sum of DBs per Time)
    SELECT strftime(bucket, '\''%m-%d %H:%M'\'') AS time, '\'' Total'\'' AS db, sum(growth) FROM binned GROUP BY 1
    UNION ALL
    -- 4. Grand Total (Corner Cell)
    SELECT '\''Total'\'' AS time, '\'' Total'\'' AS db, sum(growth) FROM binned
  )
  SELECT * FROM source
)
ON time
USING round(sum(growth) / 1024 / 1024, 2)
ORDER BY Total DESC';
    local interval=${1:?};
    shift;
    local db=$(DB-files-stat "${@:1:2}");
    shift 2;
    jq -nr "\"$sql\"" "" --arg interval "$interval" | duckdb "$db" "$@"
}
fsl:files-stat () 
{ 
    local perl='BEGIN { $t = time; $j = JSON::PP->new->utf8 }
chomp;
@s = lstat($_);
next unless @s;
print $j->encode([$t, $s[9], $s[7], $_]), "\n"';
    ( cd ${1:?} && find -type f -print0 | perl -MJSON::PP -0 -ne "$perl" )
}
fsl:get-files-stat () 
{ 
    local jq='$ARGS.positional as [ $node, $path ] | $path / "/" | map(select(length > 0)) | join("-") as $tag | "with-lib fsl -- files-stat \($path) | ssh \($node) -l root bash | gzip > tmp/\($node)-\($tag)-\(now | round).js.gz"';
    : ${2:?};
    bajl:self -nr --args "$@"
}
fsl:ingest-stat () 
{ 
    local sql='CREATE TABLE IF NOT EXISTS fsdb (
  date TIMESTAMP,
  mdate TIMESTAMP,
  size BIGINT,
  suf VARCHAR,
  path VARCHAR[]
);

INSERT INTO fsdb SELECT
  to_timestamp((js.json->0)::BIGINT),
  to_timestamp((js.json->1)::BIGINT),
  (js.json->2)::BIGINT,
  regexp_extract(js.json->>3, '\''\\.([^./]+)$'\'', 1),
  list_filter(string_split(js.json->>3, '\''/'\''), x -> x != '\''.'\'')
FROM read_json_auto('\''\($js)'\'') js';
    local jsgz=$(use latest-files-stat "$@") db=$(DB-files-stat "$@");
    jq -nr "\"$sql\"" "" --arg js $jsgz | duckdb $db
}
fsl:latest-files-stat () 
{ 
    local jq='$ARGS.positional as [ $node, $path ] | $path / "/" | map(select(length > 0)) | join("-") as $tag | "ls tmp/\($node)-\($tag)-[0-9]*.js.gz | tail -1"';
    : ${2:?};
    bajl:self -nr --args "$@"
}
fsl:list-deleted () 
{ 
    local jq='SELECT * from fsdb WHERE size = NULL';
    local db=$(DB-files-stat "$@");
    jq -nr "\"$sql\"" "" | duckdb "$db"
}
fsl:loop-next-files-stat () 
{ 
    while true; do
        sleep $((3600 - $(date +%s) % 3600));
        fsl:next-files-stat "$@";
    done
}
fsl:mark-deleted () 
{ 
    local sql='INSERT INTO fsdb
WITH meta AS (
  SELECT
    MAX(date) as curr_t,
    MAX(date) FILTER (WHERE date < (SELECT MAX(date) FROM fsdb)) as prev_t
  FROM fsdb
),
deleted_paths AS (
  -- Files present in Previous but missing in Current
  SELECT path FROM fsdb, meta WHERE date = meta.prev_t
  EXCEPT
  SELECT path FROM fsdb, meta WHERE date = meta.curr_t
)
SELECT
  meta.curr_t AS date,
  NULL AS mdate,
  NULL AS size,  -- The Deletion Marker
  NULL AS suf,
  path
FROM deleted_paths, meta';
    jq -nr "\"$sql\"" "" | duckdb tmp/2.db
}
fsl:next-files-stat () 
{ 
    fsl:use get-files-stat "$@";
    fsl:ingest-stat "$@"
}
fsl:prune-dedup () 
{ 
    local sql='DELETE FROM fsdb
WHERE rowid IN (
    SELECT rowid FROM (
        SELECT
            rowid,
            date,
            size,
            LAG(size) OVER (PARTITION BY path ORDER BY date) AS prev_size
        FROM fsdb
    )
    WHERE size = prev_size
      -- CRITICAL: Protect the most recent snapshot regardless of duplication
      AND date < (SELECT MAX(date) FROM fsdb)
)';
    jq -nr "\"$sql\"" "" | duckdb tmp/1.db
}
fsl:prune-fsdb () 
{ 
    local sql='DELETE FROM fsdb
WHERE date NOT IN (
    -- 1. Keep everything recent (younger than 2 days)
    SELECT date FROM fsdb
    WHERE date >= current_date - INTERVAL '\''\($h_age)'\''

    UNION ALL

    -- 2. Keep 1st of the Hour (between 2 days and 7 days old)
    SELECT min(date) FROM fsdb
    WHERE date < current_date - INTERVAL '\''\($h_age)'\''
      AND date >= current_date - INTERVAL '\''\($d_age)'\''
    GROUP BY date_trunc('\''hour'\'', date)

    UNION ALL

    -- 3. Keep 1st of the Day (Midnight) (between 7 days and 1 month old)
    SELECT min(date) FROM fsdb
    WHERE date < current_date - INTERVAL '\''\($d_age)'\''
      AND date >= current_date - INTERVAL '\''\($w_age)'\''
    GROUP BY date_trunc('\''day'\'', date)

    UNION ALL

    -- 4. Keep 1st of the Week (Monday) (older than 1 month)
    SELECT min(date) FROM fsdb
    WHERE date < current_date - INTERVAL '\''\($w_age)'\''
    GROUP BY date_trunc('\''week'\'', date)
);';
    local h_age="${1:-2 days}";
    local d_age="${2:-7 days}";
    local w_age="${3:-1 month}";
    local db=$(DB-files-stat "$@");
    jq -nr "\"$sql\"" "" --arg h_age "$h_age" --arg d_age "$d_age" --arg w_age "$w_age" | duckdb "$db"
}
fsl:purge-before () 
{ 
    local sql='DELETE FROM fsdb WHERE date < '\''\($limit)'\''::TIMESTAMP';
    local limit="${1:?}";
    shift;
    local db=$(DB-files-stat "$@");
    jq -nr "\"$sql\"" "" --arg limit "$limit" | duckdb "$db"
}
fsl:report-db-daily () 
{ 
    local sql='COPY (
  WITH snapshot_dates AS (
    SELECT MAX(date) as snap_date
    FROM fsdb
    GROUP BY time_bucket(INTERVAL '\''\($interval)'\'', date)
  )
  SELECT
    time_bucket(INTERVAL '\''\($interval)'\'', date) AS report_date,
    path[1] AS db_name,
    SUM(size) AS total_bytes,
    ROUND(SUM(size) / 1024.0 / 1024.0, 2) AS total_mb
  FROM fsdb
  WHERE date IN (SELECT snap_date FROM snapshot_dates)
    AND len(path) >= 2
  GROUP BY 1, 2
  ORDER BY 1 DESC, 2 ASC
) TO '\''/dev/stdout'\'' (HEADER, DELIMITER '\'','\'')';
    local csv=$(DB-files-stat-period "${@:1:3}")-$(date +%F).csv;
    local interval=${1:?};
    shift;
    local db=$(DB-files-stat "${@:1:2}");
    shift 2;
    jq -nr "\"$sql\"" "" --arg interval "$interval" | duckdb "$db" "$@" > $csv
}
fsl:run-sql () 
{ 
    local db=$(DB-files-stat "${@:1:2}");
    shift 2;
    jq -nr "\"$sql\"" "" | duckdb "$db" "$@"
}
