 (\n    SELECT rowid FROM (\n        SELECT\n            rowid,\n            date,\n            size,\n            LAG(size) OVER (PARTITION BY path ORDER BY date) AS prev_size\n        FROM fsdb\n    )\n    WHERE size = prev_size\n      -- CRITICAL: Protect the most recent snapshot regardless of duplication\n      AND date < (SELECT MAX(date) FROM fsdb)\n)","sh":"#local db=$(DB-files-stat \"$@\")\n#jq -nr \"\\\"$sql\\\"\" \"\" | duckdb \"$db\"\njq -nr \"\\\"$sql\\\"\" \"\" | duckdb tmp/1.db"},{"ns":"fsl","id":"mark-deleted","sql":"INSERT INTO fsdb\nWITH meta AS (\n  SELECT\n    MAX(date) as curr_t,\n    MAX(date) FILTER (WHERE date < (SELECT MAX(date) FROM fsdb)) as prev_t\n  FROM fsdb\n),\ndeleted_paths AS (\n  -- Files present in Previous but missing in Current\n  SELECT path FROM fsdb, meta WHERE date = meta.prev_t\n  EXCEPT\n  SELECT path FROM fsdb, meta WHERE date = meta.curr_t\n)\nSELECT\n  meta.curr_t AS date,\n  NULL AS mdate,\n  NULL AS size,  -- The Deletion Marker\n  NULL AS suf,\n  path\nFROM deleted_paths, meta","sh":"#local db=$(DB-files-stat \"$@\")\n#jq -nr \"\\\"$sql\\\"\" \"\" | duckdb \"$db\"\njq -nr \"\\\"$sql\\\"\" \"\" | duckdb tmp/2.db"},{"ns":"fsl","id":"list-deleted","jq":"SELECT * from fsdb WHERE size = NULL","sh":"local db=$(DB-files-stat \"$@\")\njq -nr \"\\\"$sql\\\"\" \"\" | duckdb \"$db\""},{"ns":"fsl","id":"view-snapshot","sql":"WITH boundary AS (SELECT MAX(date) as max_d FROM fsdb)\nSELECT\n  LEAST('\''\\($target)'\''::TIMESTAMP, boundary.max_d) AS date,\n  arg_max(mdate, date) AS mdate,\n  arg_max(size, date) AS size,\n  path\nFROM fsdb, boundary\nWHERE fsdb.date <= '\''\\($target)'\''::TIMESTAMP\nGROUP BY path, boundary.max_d\nHAVING size IS NOT NULL","sh":"local target=\"${1:-now}\"\nlocal db=$(DB-files-stat \"$@\")\njq -nr \"\\\"$sql\\\"\" \"\" --arg target \"$target\" | duckdb -nullvalue '\'' '\'' \"$db\""},{"ns":"fsl","id":"view-snapshot-2","sql":"WITH boundary AS (SELECT MAX(date) as max_d FROM fsdb)\nSELECT\n  -- Cast input string to timestamp; clamp to DB end if future\n  LEAST('\''\\($target)'\''::TIMESTAMP, boundary.max_d) AS date,\n  arg_max(mdate, date) AS mdate,\n  arg_max(size, date) AS size,\n  path\nFROM fsdb, boundary\nWHERE fsdb.date <= '\''\\($target)'\''::TIMESTAMP\nGROUP BY path, boundary.max_d","sh":"local target=\"${1:?}\"; shift\n#local db=$(DB-files-stat \"$@\")\n#jq -nr \"\\\"$sql\\\"\" \"\" --arg target \"$target\" | duckdb -nullvalue '\'' '\'' \"$db\"\njq -nr \"\\\"$sql\\\"\" \"\" --arg target \"$target\" | duckdb tmp/2.db"},{"ns":"fsl","id":"view-snapshot-1","sql":"SELECT\n  '\''\\($target)'\''::TIMESTAMP AS date,\n  arg_max(mdate, date) AS mdate,\n  arg_max(size, date) AS size,\n  path\nFROM fsdb\nWHERE date <= '\''\\($target)'\''::TIMESTAMP\nGROUP BY path","sh":"local target=\"${1:?}\"; shift\n#local db=$(DB-files-stat \"$@\")\n#jq -nr \"\\\"$sql\\\"\" \"\" --arg target \"$target\" | duckdb -nullvalue '\'' '\'' \"$db\"\njq -nr \"\\\"$sql\\\"\" \"\" --arg target \"$target\" | duckdb -nullvalue '\'' '\'' tmp/2.db"}]'
}
fsl:use () 
{ 
    source <(eval "$@")
}
fsl:view-snapshot () 
{ 
    local sql='WITH boundary AS (SELECT MAX(date) as max_d FROM fsdb)
SELECT
  LEAST('\''\($target)'\''::TIMESTAMP, boundary.max_d) AS date,
  arg_max(mdate, date) AS mdate,
  arg_max(size, date) AS size,
  path
FROM fsdb, boundary
WHERE fsdb.date <= '\''\($target)'\''::TIMESTAMP
GROUP BY path, boundary.max_d
HAVING size IS NOT NULL';
    local target="${1:-now}";
    local db=$(DB-files-stat "$@");
    jq -nr "\"$sql\"" "" --arg target "$target" | duckdb -nullvalue ' ' "$db"
}
fsl:view-snapshot-1 () 
{ 
    local sql='SELECT
  '\''\($target)'\''::TIMESTAMP AS date,
  arg_max(mdate, date) AS mdate,
  arg_max(size, date) AS size,
  path
FROM fsdb
WHERE date <= '\''\($target)'\''::TIMESTAMP
GROUP BY path';
    local target="${1:?}";
    shift;
    jq -nr "\"$sql\"" "" --arg target "$target" | duckdb -nullvalue ' ' tmp/2.db
}
fsl:view-snapshot-2 () 
{ 
    local sql='WITH boundary AS (SELECT MAX(date) as max_d FROM fsdb)
SELECT
  -- Cast input string to timestamp; clamp to DB end if future
  LEAST('\''\($target)'\''::TIMESTAMP, boundary.max_d) AS date,
  arg_max(mdate, date) AS mdate,
  arg_max(size, date) AS size,
  path
FROM fsdb, boundary
WHERE fsdb.date <= '\''\($target)'\''::TIMESTAMP
GROUP BY path, boundary.max_d';
    local target="${1:?}";
    shift;
    jq -nr "\"$sql\"" "" --arg target "$target" | duckdb tmp/2.db
}
ns:fsl () 
{ 
    fsl:${1:?} "${@:2}"
}
bajl:self () 
{ 
    jq "$jq" "$@"
}
